        // the lobby draws every frame: Characters.Imported (disk) asked again at most every 2 s per skin
        private readonly Dictionary<string, (bool Yes, long At)> _badgeImported = new(StringComparer.OrdinalIgnoreCase);

        private bool TrooperImported(string skin)
        {
            long now = Environment.TickCount64;
            if (_badgeImported.TryGetValue(skin, out var seen) && now - seen.At < 2000) return seen.Yes;
            bool yes = PickerHdRoot is { } hd && Characters.Imported(hd, skin);
            _badgeImported[skin] = (yes, now);
            return yes;
        }

        // a seat's hand-picked badge pair in lobby colour `colour`, or null (BadgePair's auto pick)
        private ((byte R, byte G, byte B) A, (byte R, byte G, byte B) B)? HandBadge(MatchPlayer p, int colour)
        {
            string who = Characters.IsOriginal(p.Skin) ? p.Hunter.ToString() : p.Skin!;
            if (StandinPictures.Of(who) != null && !who.Equals("DarkSamusStandin", StringComparison.OrdinalIgnoreCase)
                && !TrooperImported(who))
            {
                who = "ds_" + who;
            }
            if (!s_handBadges.TryGetValue(who, out uint[]? row) || colour < 0 || 2 * colour + 1 >= row.Length) return null;
            static (byte, byte, byte) Rgb(uint c) => ((byte)(c >> 16), (byte)(c >> 8), (byte)c);
            return (Rgb(row[2 * colour]), Rgb(row[2 * colour + 1]));
        }
